// Order uploaded files by the date in the filename: oldest -> prev (first day), newest -> curr (last day).
const item = $('On form submission').first();
const bin = item.binary || {};
const files = Object.keys(bin).map((k) => {
  const b = bin[k];
  const name = String(b.fileName || k);
  const m = name.match(/(\d{4}-\d{2}-\d{2})/);
  return { binary: b, name, date: m ? m[1] : '' };
});
if (files.length < 2) {
  throw new Error('Upload at least two days of files from the week.');
}
files.sort((a, b) => (a.date || '').localeCompare(b.date || ''));
const prev = files[0];
const curr = files[files.length - 1];
return [{ json: { prevDate: prev.date, currDate: curr.date }, binary: { curr: curr.binary, prev: prev.binary } }];

// Per-owner first-day vs last-day, with a ticket -> URL map for clickable links.
const KNOWN = ['Julio Calderon', 'Pedro Faria', 'Zubair Malik', 'Deepak Padliya', 'Sel Soyer'];
const rows = $input.all().map((i) => i.json);
const url = new Map();
const byOwner = new Map();
for (const o of KNOWN) byOwner.set(o, { curr: new Set(), prev: new Set() });
for (const r of rows) {
  const owner = String(r['Assignment'] ?? '').trim();
  const ticket = String(r['Overdue Tickets'] ?? '').trim();
  const u = String(r['Ticket URL'] ?? '').trim();
  if (!owner || !ticket) continue;
  if (u && !url.has(ticket)) url.set(ticket, u);
  if (!byOwner.has(owner)) byOwner.set(owner, { curr: new Set(), prev: new Set() });
  if (r.period === 'curr') byOwner.get(owner).curr.add(ticket);
  else if (r.period === 'prev') byOwner.get(owner).prev.add(ticket);
}
const prevDate = $('Order uploads').first().json.prevDate || '';
const currDate = $('Order uploads').first().json.currDate || '';
const extras = [...byOwner.keys()].filter((o) => !KNOWN.includes(o)).sort();
const owners = [...KNOWN, ...extras];
const perOwner = owners.map((owner) => {
  const rec = byOwner.get(owner) || { curr: new Set(), prev: new Set() };
  const current = [...rec.curr].sort();
  const added = [...rec.curr].filter((t) => !rec.prev.has(t)).sort();
  const cleared = [...rec.prev].filter((t) => !rec.curr.has(t)).sort();
  return { owner, start: rec.prev.size, end: rec.curr.size, net: rec.curr.size - rec.prev.size, current, added, cleared };
});
const urlMap = Object.fromEntries(url);
const totalStart = perOwner.reduce((a, o) => a + o.start, 0);
const totalEnd = perOwner.reduce((a, o) => a + o.end, 0);
const lines = perOwner.map((o) =>
  `- ${o.owner}: ${o.start} -> ${o.end} (net ${o.net >= 0 ? '+' : ''}${o.net}); new [${o.added.join(', ') || 'none'}]; cleared [${o.cleared.join(', ') || 'none'}]`);
const prompt =
`You are a security operations analyst. Using ONLY the data below, write a very concise weekly report on Network Engineering overdue vulnerability tickets. Do not invent or change any numbers or ticket IDs.

Write EXACTLY five short paragraphs, one for each owner, in this order: ${KNOWN.join(', ')}. Each paragraph is 2-3 sentences: name the owner, give their start-to-end count and net change, and call out their most notable new or cleared tickets (or say they were unchanged). No headings, no bullets, no preamble or conclusion - just the five paragraphs separated by blank lines.

Week ${prevDate} to ${currDate}. Team total ${totalStart} -> ${totalEnd} overdue.
${lines.join('\n')}`;
return [{ json: { prompt, perOwner, urlMap, prevDate, currDate, totalStart, totalEnd } }];

// Narrative + per-owner table with comma-separated clickable ticket links.
const a = $('Analyze week').first().json;
const urlMap = a.urlMap || {};
let narrative = '';
try {
  const c = $('Write report').first().json;
  narrative = String(c.text ?? c.output ?? c.response ?? '').trim();
} catch (e) { narrative = ''; }
if (!narrative) narrative = '(AI narrative unavailable - check the Azure OpenAI credential and deployment on the "Azure OpenAI Chat Model" node.)';

const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const escAttr = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/"/g, '&quot;').replace(/</g, '&lt;');
const link = (t) => { const u = urlMap[t]; return u ? `<a href="${escAttr(u)}">${esc(t)}</a>` : esc(t); };
const linkList = (arr) => ((arr || []).map(link).join(', ')) || '<span class="muted">none</span>';

const narrativeHtml = esc(narrative).split(/\n\n+/).map((p) => `<p>${p.replace(/\n/g, '<br>')}</p>`).join('\n');

const rowsHtml = (a.perOwner || []).map((o) => `
  <tr>
    <td>${esc(o.owner)}</td>
    <td class="n">${o.start}</td>
    <td class="n">${o.end}</td>
    <td class="n ${o.net > 0 ? 'up' : (o.net < 0 ? 'down' : '')}">${o.net >= 0 ? '+' : ''}${o.net}</td>
    <td>${linkList(o.current)}</td>
    <td>${linkList(o.added)}</td>
    <td>${linkList(o.cleared)}</td>
  </tr>`).join('');

const html = `<!doctype html><html><head><meta charset="utf-8">
<title>TVM weekly report ${esc(a.prevDate)} to ${esc(a.currDate)}</title>
<style>
body{font-family:Segoe UI,Arial,sans-serif;max-width:1000px;margin:24px auto;padding:0 16px;color:#1b1b1b}
h1{font-size:20px;margin-bottom:2px} h2{font-size:15px;margin-top:28px}
.sub{color:#666;font-size:13px}
table{border-collapse:collapse;width:100%;font-size:13px;margin-top:8px}
th,td{border:1px solid #ddd;padding:6px 8px;text-align:left;vertical-align:top}
th{background:#f3f4f6} td.n{text-align:right;white-space:nowrap} .up{color:#b00020} .down{color:#0a7d33}
a{color:#0b5cad;text-decoration:none} a:hover{text-decoration:underline} .muted{color:#999} p{line-height:1.5}
</style></head><body>
<h1>TVM Overdue Tickets - Weekly Report</h1>
<div class="sub">${esc(a.prevDate)} to ${esc(a.currDate)} &middot; team ${a.totalStart} &rarr; ${a.totalEnd} overdue</div>
<h2>Summary</h2>
${narrativeHtml}
<h2>By owner</h2>
<table>
<tr><th>Owner</th><th>Start</th><th>End</th><th>Net</th><th>Currently overdue</th><th>New this week</th><th>Cleared this week</th></tr>
${rowsHtml}
</table>
</body></html>`;

const fileName = `tvm-weekly-report-${a.prevDate}-to-${a.currDate}.html`;
return [{ json: { fileName }, binary: { data: { data: Buffer.from(html, 'utf8').toString('base64'), mimeType: 'text/html', fileName, fileExtension: 'html' } } }];
